/* LiczMat website — translations that only the generated sub-pages use
   (/kalkulatory/, /kalkulatory/<slug>/, /poradniki/<slug>/, /sklepy/, /app/, /p/).

   This file is a BUILD INPUT, not a browser asset: `scripts/build.mjs` merges it
   with assets/i18n.js and emits one flat per-language bundle (assets/i18n.<lang>.js)
   that the pages actually load. Keys must exist in all thirteen languages — the build
   fails loudly when one is missing, so a page can never end up half-translated.

   Key prefixes:
     nav_, bc_, foot_   navigation and breadcrumbs
     calchub_           the /kalkulatory/ hub
     hwc_               the "how we calculate" block on a calculator page
     note_<calcId>      the one caveat that matters for that calculator
     guides_, g_        /poradniki/
     storespage_        /sklepy/
     acct_              the account + sync copy (app and web)
     app_               the /app/ workspace
     share_             the read-only /p/<token> view
*/

