    ck_life_google: "Wg zasad Google",
    ck_p_consent: "Twoja decyzja w sprawie analityki. Bez niej baner pytałby przy każdym wejściu.",
    ck_p_lang: "Język, który wybrałeś przełącznikiem, żeby kolejne wejście trafiło od razu w niego.",
    ck_p_currency: "Waluta, w której liczysz ceny. Wybierasz ją niezależnie od języka.",
    ck_p_theme: "Motyw jasny albo ciemny, jeśli wybrałeś go ręcznie zamiast zostawić systemowy.",
    ck_p_signed_in: "Poziom konta (LiczMat albo LiczMat Pro) zapamiętany przy logowaniu. Kalkulatory nie ładują Firebase, a muszą wiedzieć, czy proponować konto. Nie ma w nim adresu e-mail ani innych danych o Tobie i niczego nie odblokowuje.",
    ck_p_remember: "Czy zostajesz zalogowany po zamknięciu przeglądarki. Ustawiasz to przy logowaniu albo w profilu; wartość dotyczy tylko tego urządzenia.",
    ck_p_redirect: "Zabezpieczenie przed pętlą przekierowań przy zmianie języka.",
    ck_p_workspace: "Twoje projekty, pomieszczenia i pozycje kosztorysu zapisane bez logowania.",
    ck_p_active: "Do którego projektu zapisać wynik — wybierasz to przy „Dodaj do projektu”.",
    ck_p_recent: "Które kalkulatory były ostatnio używane, żeby pulpit mógł je pokazać. Sama nazwa narzędzia i data — bez wpisanych liczb i bez wyników.",
    ck_p_ga: "Google Analytics: anonimowy, zbiorczy ruch na stronie. Zapisywane dopiero po Twojej zgodzie.",
    ck_p_firebase: "Sesja logowania w „Moje konto” i lokalna kopia danych konta. Tylko po zalogowaniu.",
    ck_p_maps: "Mapa Google osadzona na stronie sklepów ustawia własne pliki Google, gdy ją wyświetlisz.",
    guide_calcs_back: "Poradniki z tym kalkulatorem",

    /* Guides added 2026-08-08: adhesive, skim coat, ETICS, board cutting. */
    g_klej_t: "Ile kleju do płytek",
    g_klej_d: "Zużycie kleju zależy od grzebienia, a ten od formatu płytki. Do tego fuga i sama płytka z zapasem na docinki.",
    g_klej_s1: "Wybierz grzebień pod format płytki: 6 mm do małych ściennych, 8–10 mm do gresu 60×60, 12 mm i metoda kombinowana do wielkiego formatu.",
    g_klej_s2: "Pomnóż powierzchnię przez zużycie z worka (typowo 4 kg/m² przy grzebieniu 6 mm, 5 kg/m² przy 10 mm) i podziel przez wagę worka.",
    g_klej_s3: "Policz osobno fugę — zależy od wymiaru płytki, jej grubości i szerokości spoiny — oraz same płytki z zapasem na docinki.",
    g_klej_tip: "Zużycie z worka dotyczy równego podłoża. Krzywa ściana wypija znacznie więcej kleju niż mówi etykieta; przy nierównościach ponad 5 mm najpierw wyrównaj podłoże, bo klej jest droższy od wylewki.",
    g_gladz_t: "Ile gładzi na ścianę",
    g_gladz_d: "Gładź liczy się w kilogramach na metr kwadratowy i milimetr warstwy. Dwie cienkie warstwy zamiast jednej grubej.",
    g_gladz_s1: "Policz pole ścian i sufitu i odejmij okna oraz drzwi. Powierzchnia to punkt wyjścia dla każdej warstwy.",
    g_gladz_s2: "Przyjmij zużycie z worka: gładź gipsowa około 1 kg/m² na milimetr warstwy, polimerowa około 1,2 kg/m². Pomnóż przez grubość warstwy.",
    g_gladz_s3: "Pomnóż przez liczbę warstw i podziel przez wagę worka. Zaokrąglij w górę — resztki worka nie kupisz.",
    g_gladz_tip: "Na surowym tynku pierwsza warstwa schodzi grubiej niż zakłada etykieta, bo wypełnia nierówności. Licz pierwszą warstwę jako 1,5 mm, a drugą jako 0,5 mm, i najpierw zagruntuj — bez gruntu gładź ciągnie wodę i pyli.",
    g_ocieplenie_t: "Ocieplenie domu styropianem",
    g_ocieplenie_d: "System ETICS to styropian, klej, kołki, siatka, warstwa zbrojąca i tynk. Każdy element liczy się z tej samej powierzchni.",
    g_ocieplenie_s1: "Policz pole elewacji: obwód budynku razy wysokość, minus okna i drzwi. Ościeża licz osobno, jeśli je ocieplasz.",
    g_ocieplenie_s2: "Dobierz grubość styropianu i policz paczki. Do tego kołki: typowo 6 sztuk na m², przy narożnikach i wyżej niż 8 m więcej. Klej licz dwa razy, osobno do przyklejania i osobno do warstwy zbrojącej.",
    g_ocieplenie_s3: "Siatkę licz z zapasem około 10 % na zakłady, a tynk cienkowarstwowy z jego własnego zużycia na m².",
    g_ocieplenie_tip: "Liczba kołków to nie jedna wartość na cały dom. Strefa narożna wymaga ich gęściej niż środek ściany, a powyżej 8 m budynek wchodzi w wyższą strefę wiatrową. Sprawdź projekt albo wytyczne systemu, zanim zamówisz.",
    g_rozkroj_t: "Rozkrój płyty meblowej bez odpadu",
    g_rozkroj_d: "Ile płyt kupić na listę formatek i jak je poukładać, żeby odpad był jak najmniejszy. Rzaz piły też zabiera materiał.",
    g_rozkroj_s1: "Wypisz formatki: szerokość, długość i sztuki. Dodaj naddatek na okleinę, jeśli obrzeże ma być nakładane po docięciu.",
    g_rozkroj_s2: "Podaj format płyty i rzaz piły. Piła panelowa zabiera około 3–4 mm na każde cięcie; przy kilkudziesięciu cięciach to całe centymetry.",
    g_rozkroj_s3: "Sprawdź, czy formatki mogą być obracane. Płyta z usłojeniem albo wzorem nie może, i wtedy odpad rośnie — policz oba warianty i porównaj.",
    g_rozkroj_tip: "Wynik to plan cięcia, nie zamówienie. Zanim zamówisz, sprawdź, czy każda formatka leży tak, jak obrócił ją algorytm. Przy usłojeniu obrót zmienia wygląd frontu, nawet gdy wymiar się zgadza.",

