    guides_title: "Guides",
    guides_lead: "Short instructions: from room dimensions to a shopping list. Every step links to the calculator that does the maths.",
    guides_meta: "LiczMat guides: how much paint for a room, how many tiles and how much adhesive for a bathroom. How many floor panels, how many profiles for a stud wall.",
    guide_steps_t: "Step by step",
    guide_calcs_t: "Calculators used in this guide",
