    ck_p_signed_in: "Die Kontostufe (LiczMat oder LiczMat Pro), bei der Anmeldung gemerkt. Die Rechner laden kein Firebase und müssen trotzdem wissen, ob sie ein Konto vorschlagen. Sie enthält keine E-Mail-Adresse und schaltet nichts frei.",
