    g_malowanie_t: "Kolik barvy na pokoj",
    g_malowanie_d: "Plocha stěn a stropu, odečtené otvory, přepočet na celá balení s rezervou na druhý nátěr.",
    g_malowanie_s1: "Změř pokoj: délku, šířku a výšku. Obvod krát výška dá plochu stěn, délka krát šířka strop.",
    g_malowanie_s2: "Odečti okna a dveře. Typické okno má asi 1,5 m², typické dveře asi 1,8 m².",
    g_malowanie_s3: "Vyděl vydatností uvedenou na obalu a vynásob počtem nátěrů. Zaokrouhli nahoru na celá balení.",
    g_malowanie_tip: "Vydatnost na etiketě platí pro hladký, napenetrovaný podklad. Savá omítka spotřebuje víc, takže počítej s rezervou nebo nejdřív napenetruj.",
    g_plytki_t: "Kolik obkladů a lepidla do koupelny",
    g_plytki_d: "Podlaha a stěny v metrech čtverečních, rezerva na prořez, lepidlo a spárovací hmota přepočtené na pytle.",
    g_plytki_s1: "Počítej podlahu a stěny zvlášť. U stěn vezmi obvod krát výšku obkladu a odečti dveře a okno.",
    g_plytki_s2: "Přidej rezervu na prořez: 5–7% při rovné vazbě, 10–15% u velkého formátu nebo diagonální vazby.",
    g_plytki_s3: "Lepidlo spočítej z vydatnosti pro zvolené zubové hladítko, spárovací hmotu z rozměru dlaždice a šířky spáry.",
    g_plytki_tip: "Kupuj obklady z jedné výrobní šarže. Šarže se liší odstínem i kalibrem a za měsíc už ta samá v obchodě nebude.",
    g_panele_t: "Kolik panelů na podlahu",
    g_panele_d: "Plocha podlahy, rezerva na prořez a přepočet na celá balení.",
    g_panele_s1: "Změř podlahu: délka krát šířka. Výklenky a arkýře změř zvlášť a přičti.",
    g_panele_s2: "Přidej rezervu na prořez: 5% při rovném kladení podél delší stěny, 10% při diagonálním kladení.",
    g_panele_s3: "Vyděl plochou balení uvedenou na obalu a zaokrouhli nahoru na celá balení.",
    g_panele_tip: "Nech si jedno celé balení do rezervy. Poškozené prkno vyměníš jen tehdy, když máš přesně stejný dekor.",
    g_sciana_t: "SDK příčka: profily a desky",
    g_sciana_d: "Kolik profilů CW a UW, kolik sádrokartonových desek a kolik vaty na příčku daných rozměrů.",
    g_sciana_s1: "Zadej šířku a výšku příčky a rozteč profilů — nejčastěji 60 cm, pod těžším obkladem 40 cm.",
    g_sciana_s2: "Profily CW vycházejí z rozteče, profily UW jsou podlaha a strop, tedy dvojnásobek délky stěny.",
    g_sciana_s3: "Desky počítej na obě strany příčky s rezervou 10% na prořez. Vatu počítej na plochu stěny.",
    g_sciana_tip: "Desky kladem prostřídej, aby spáry na jedné straně nevyšly na stejné místo jako na druhé. Stěna je tuhčí a spáry méně praskají.",
    storespage_title: "Stavebniny ve tvém okolí",
    storespage_lead: "Najdi market, velkoobchod nebo stavebniny podle lokality nebo názvu.",
    storespage_meta: "Najdi stavebniny v okolí: hobbymarkety, velkoobchody a stavebniny na mapě, s trasou k vybranému místu.",
    note_coverage: "Vydatnost na etiketě (m²/l nebo m²/balení) platí pro hladký, napenetrovaný podklad. Savá omítka spotřebuje víc. Otvory odečítej jen tehdy, když je nemaluješ.",
    note_waste: "Rezerva 5–7% stačí při rovné vazbě. Velký formát, diagonální nebo vazba na cihlu potřebují 10–15%. Kupuj z jedné šarže.",
    note_wallpaper: "U tapety s raportem se každý pás prodlouží na celý násobek raportu, takže z role vyjde méně pásů. Raport 0 znamená tapetu bez vzoru k napojení.",
    note_linear: "Prořez pily se odečítá při každém dalším řezu v tyči. Návrh řezu nemusí být optimální.",
    note_sheet: "Gilotinový nářez: každý řez jde skrz celou desku, jako na formátovací pile. Otáčení vypni, když má deska kresbu nebo směrový dekor.",
    note_concrete: "Přepočet předpokládá pytel 25 kg suché směsi, který dá asi 12,5 l betonu. Zkontroluj vydatnost na pytli, liší se podle výrobce.",
    note_mortar: "Spotřeba lepidla závisí na zubu hladítka a rovinnosti podkladu. Uvedená hodnota je z technického listu; na křivé stěně může vzrůst o polovinu.",
    note_screed: "Přepočet předpokládá hustotu asi 2,0 kg na litr malty. Anhydritové a lehčené potěry mají jinou hustotu — zkontroluj pytel.",
    note_grout: "Spotřeba spárovací hmoty roste se šířkou spáry a tloušťkou dlaždice a klesá s formátem. U velké dlažby na úzké spáře vyjde velmi málo.",
    note_masonry: "Počet kusů na m² vychází z rozměru tvárnice včetně spáry. Rezerva 5% pokryje prořez a praskliny při dopravě.",
    note_insulation: "Počet hmoždinek závisí na výšce budovy a větrové oblasti — 6 ks/m² je typické pro přízemí a první patro. Síťku počítej s přesahem 10%.",
    note_studwall: "Rozteč 60 cm je standard pod desku 1,2 m. Pod těžší obklad nebo dlažbu jdi na 40 cm. Desky počítej na obě strany.",
    note_ceiling: "Rozteč nosných CD 40 cm a závěsů 90 cm je typický podhled pod jednu desku. Při vyšším zatížení je nutné rozteče zhustit.",
    note_drylining: "Metoda na lepicí terče funguje jen na rovném, nosném podkladu. Větší nerovnosti vyžadují rošt.",
    note_sheathing: "Výsledek je počet celých desek bez plánu nářezu. Když chceš vědět, jak je rozřezat, použij kalkulačku nářezu desek 2D.",
