    g_klej_d: "Spotřeba lepidla se řídí hřebenem a hřeben formátem obkladu. K tomu spárovací hmota a samotné obklady s prořezem.",
    g_klej_s1: "Vyber hřeben podle formátu: 6 mm na malé obklady, 8–10 mm na dlažbu 60×60, 12 mm a kombinovaná metoda na velký formát.",
    g_klej_s2: "Vynásob plochu spotřebou z pytle (typicky 4 kg/m² při hřebenu 6 mm, 5 kg/m² při 10 mm) a vyděl hmotností pytle.",
    g_klej_s3: "Spárovací hmotu počítej zvlášť — řídí se rozměrem obkladu, jeho tloušťkou a šířkou spáry — a obklady s prořezem.",
    g_klej_tip: "Spotřeba na pytli platí pro rovný podklad. Křivá stěna vypije podstatně víc lepidla, než říká etiketa. Nad zhruba 5 mm nerovnosti nejdřív vyrovnej podklad: lepidlo je dražší než stěrka.",
    g_gladz_t: "Kolik štuku na stěnu",
    g_gladz_d: "Štuk se počítá v kilogramech na metr čtvereční a milimetr vrstvy. Dvě tenké vrstvy místo jedné tlusté.",
    g_gladz_s1: "Spočítej plochu stěn a stropu a odečti okna a dveře. Tahle plocha je základ pro každou vrstvu.",
    g_gladz_s2: "Vezmi spotřebu z pytle: sádrový štuk asi 1 kg/m² na milimetr, polymerový asi 1,2 kg/m². Vynásob tloušťkou vrstvy.",
    g_gladz_s3: "Vynásob počtem vrstev a vyděl hmotností pytle. Zaokrouhli nahoru — půl pytle nekoupíš.",
    g_gladz_tip: "Na syrové omítce jde první vrstva silněji, než etiketa předpokládá, protože vyplňuje nerovnosti. Počítej první vrstvu jako 1,5 mm a druhou jako 0,5 mm a napřed penetruj — bez penetrace štuk táhne vodu a práší.",
    g_ocieplenie_t: "Zateplení domu polystyrenem",
    g_ocieplenie_d: "ETICS tvoří polystyren, lepidlo, hmoždinky, síťka, výztužná vrstva a omítka. Všechno se počítá ze stejné plochy.",
    g_ocieplenie_s1: "Spočítej plochu fasády: obvod budovy krát výška, minus okna a dveře. Ostění počítej zvlášť, pokud je zatepluješ.",
    g_ocieplenie_s2: "Vyber tloušťku polystyrenu a spočítej balíky. K tomu hmoždinky (typicky 6 na m², v rozích a nad 8 m víc) a lepidlo — zvlášť na lepení, zvlášť na výztužnou vrstvu.",
    g_ocieplenie_s3: "U síťky přidej asi 10 % na přesahy a tenkovrstvou omítku počítej z její vlastní spotřeby na m².",
    g_ocieplenie_tip: "Počet hmoždinek není jedno číslo pro celý dům. Rohová zóna je potřebuje hustěji než střed stěny a nad 8 m se budova posouvá do vyšší větrné oblasti. Před objednáním zkontroluj projekt nebo pokyny systému.",
    g_rozkroj_t: "Nářez nábytkové desky s malým prořezem",
    g_rozkroj_d: "Kolik desek koupit na seznam dílců a jak je rozložit, aby byl odpad co nejmenší. Prořez pily taky ubírá materiál.",
    g_rozkroj_s1: "Vypiš dílce: šířka, délka a kusy. Přidej nadměr na hranu, pokud se olepuje až po nářezu.",
    g_rozkroj_s2: "Zadej formát desky a prořez pily. Formátovací pila ubere asi 3–4 mm na každý řez; při pár desítkách řezů to jsou celé centimetry.",
    g_rozkroj_s3: "Rozhodni, jestli se dílce smí otáčet. Deska s kresbou nebo dekorem nesmí a odpad roste — spočítej obě varianty a porovnej.",
    g_rozkroj_tip: "Výsledek je plán řezu, ne objednávka. Před objednáním zkontroluj, jestli každý dílec leží tak, jak ho algoritmus otočil. U kresby otočení mění vzhled čela, i když rozměr sedí.",
