    ck_p_signed_in: "Úroveň účtu (LiczMat alebo LiczMat Pro) zapamätaná pri prihlásení. Kalkulačky nenačítavajú Firebase a napriek tomu musia vedieť, či ponúknuť účet. Neobsahuje e-mail ani žiadne iné údaje o tebe.",
    ck_p_remember: "Či zostávaš prihlásený po zatvorení prehliadača. Nastavuješ to pri prihlásení alebo v profile; hodnota platí len pre toto zariadenie.",
    ck_p_redirect: "Poistka proti slučke presmerovaní pri zmene jazyka.",
    ck_p_workspace: "Tvoje projekty, miestnosti a položky rozpočtu uložené bez prihlásenia.",
