    ck_p_theme: "Tema deschisă sau întunecată, dacă ai ales-o manual în loc să o lași pe cea a sistemului.",
    ck_p_signed_in: "Nivelul contului (LiczMat sau LiczMat Pro) reținut la autentificare. Calculatoarele nu încarcă Firebase și totuși trebuie să știe dacă să îți propună un cont. Nu conține adresa de e-mail și nici alte date despre tine.",
    ck_p_remember: "Dacă rămâi autentificat după închiderea browserului. Îl setezi la autentificare sau în profil; valoarea este doar pentru acest dispozitiv.",
    ck_p_redirect: "O protecție împotriva buclelor de redirecționare la schimbarea limbii.",
