    ck_p_recent: "Ce calculatoare au fost folosite ultima dată, ca panoul să le poată afișa. Doar numele uneltei și data — fără cifrele introduse și fără rezultate.",
    ck_p_ga: "Google Analytics: trafic anonim și agregat. Se scrie doar după ce accepți.",
    ck_p_firebase: "Sesiunea de autentificare din „Contul meu” și o copie locală a datelor contului. Doar după autentificare.",
    ck_p_maps: "Harta Google inclusă pe pagina magazinelor își setează propriile fișiere Google la încărcare.",
    guide_calcs_back: "Ghiduri care folosesc acest calculator",
    g_klej_t: "Cât adeziv pentru gresie",
    g_klej_d: "Consumul de adeziv urmează gletiera dințată, iar gletiera urmează formatul plăcii. Apoi chitul de rosturi și plăcile în sine, cu adaos pentru tăieturi.",
    g_klej_s1: "Alege gletiera după format: 6 mm pentru faianță mică, 8–10 mm pentru gresie 60×60, 12 mm și dublă aplicare pentru format mare.",
    g_klej_s2: "Înmulțește suprafața cu consumul de pe sac (tipic 4 kg/m² la gletieră de 6 mm, 5 kg/m² la 10 mm) și împarte la greutatea sacului.",
    g_klej_s3: "Calculează chitul separat — depinde de dimensiunea plăcii, grosimea ei și lățimea rostului — și plăcile cu adaos pentru tăieturi.",
    g_klej_tip: "Consumul de pe sac presupune un suport plan. Un perete strâmb bea mult mai mult adeziv decât spune eticheta. Peste circa 5 mm abatere, îndreaptă întâi suportul: adezivul e mai scump decât șapa autonivelantă.",
    g_gladz_t: "Cât glet pentru perete",
    g_gladz_d: "Gletul se socotește în kilograme pe metru pătrat și milimetru de strat. Două straturi subțiri în loc de unul gros.",
    g_gladz_s1: "Calculează suprafața pereților și a tavanului și scade ferestrele și ușile. Suprafața asta e punctul de plecare pentru fiecare strat.",
    g_gladz_s2: "Ia consumul de pe sac: glet de ipsos circa 1 kg/m² pe milimetru, polimeric circa 1,2 kg/m². Înmulțește cu grosimea stratului.",
    g_gladz_s3: "Înmulțește cu numărul de straturi și împarte la greutatea sacului. Rotunjește în sus — jumătate de sac nu se cumpără.",
    g_gladz_tip: "Pe tencuială brută primul strat iese mai gros decât presupune eticheta, fiindcă umple denivelările. Socotește primul strat la 1,5 mm și al doilea la 0,5 mm, și amorsează întâi — fără amorsă gletul trage apa și se praf.",
    g_ocieplenie_t: "Termoizolarea casei cu polistiren",
    g_ocieplenie_d: "Un sistem ETICS înseamnă polistiren, adeziv, dibluri, plasă, strat de armare și tencuială. Toate se calculează din aceeași suprafață.",
    g_ocieplenie_s1: "Calculează suprafața fațadei: perimetrul clădirii ori înălțimea, minus ferestre și uși. Glafurile se calculează separat, dacă le izolezi.",
    g_ocieplenie_s2: "Alege grosimea polistirenului și numără pachetele. Apoi diblurile (tipic 6 pe m², mai multe la colțuri și peste 8 m) și adezivul — unul pentru lipire, altul pentru stratul de armare.",
    g_ocieplenie_s3: "La plasă adaugă circa 10 % pentru suprapuneri, iar tencuiala decorativă se ia din consumul ei pe m².",
    g_ocieplenie_tip: "Numărul de dibluri nu e o singură cifră pentru toată casa. Zona de colț le cere mai dese decât mijlocul peretelui, iar peste 8 m clădirea intră într-o zonă de vânt superioară. Verifică proiectul sau ghidul sistemului înainte să comanzi.",
    g_rozkroj_t: "Debitarea plăcii de mobilă cu pierderi mici",
    g_rozkroj_d: "Câte plăci trebuie pentru o listă de repere și cum le așezi ca deșeul să fie cât mai mic. Tăietura pânzei consumă și ea material.",
    g_rozkroj_s1: "Scrie reperele: lățime, lungime și bucăți. Adaugă un plus pentru cant, dacă banda se pune după debitare.",
    g_rozkroj_s2: "Dă formatul plăcii și tăietura. Un ferăstrău de panel ia circa 3–4 mm la fiecare tăiere; la câteva zeci de tăieri sunt centimetri întregi.",
    g_rozkroj_s3: "Hotărăște dacă reperele pot fi rotite. O placă cu fibră sau model nu poate, și pierderea crește — calculează ambele variante și compară.",
    g_rozkroj_tip: "Rezultatul e un plan de tăiere, nu o comandă. Înainte să comanzi, verifică dacă fiecare reper stă așa cum l-a rotit algoritmul. La fibră, rotirea schimbă aspectul frontului chiar dacă dimensiunea e bună.",
    nav_app_page: "Aplicația",
