    apppage_web_link: "Calculatoare în browser",
    apppage_h_result: "Rezultatul calculului",
    apppage_result_d: "Introduci dimensiunile și materialul, iar aplicația arată câte ambalaje să cumperi și ce pierderi rămân. Debitarea include bare, plăci și tăietura fierăstrăului.",
    apppage_h_project: "Proiecte și încăperi",
    apppage_project_d: "Salvezi fiecare calcul într-un proiect și îl atribui unei camere. După autentificare se sincronizează totul: proiecte, camere, calcule, liste de cumpărături, materiale proprii, iar în Pro și clienți și oferte.",
