    g_klej_t: "Koliko ljepila za pločice",
    g_klej_d: "Potrošnja ljepila ovisi o češlju, a češalj o formatu pločice. Uz to fugir masa i same pločice s otpadom na rezanje.",
    g_klej_s1: "Odaberi češalj prema formatu: 6 mm za male zidne pločice, 8–10 mm za gres 60×60, 12 mm i kombinirana metoda za veliki format.",
    g_klej_s2: "Pomnoži površinu s potrošnjom s vreće (tipično 4 kg/m² pri češlju 6 mm, 5 kg/m² pri 10 mm) i podijeli s težinom vreće.",
    g_klej_s3: "Fugir masu računaj zasebno — ovisi o dimenziji pločice, njezinoj debljini i širini sljubnice — i pločice s otpadom.",
    g_klej_tip: "Potrošnja s vreće vrijedi za ravnu podlogu. Kriv zid popije bitno više ljepila nego što piše na etiketi. Preko otprilike 5 mm neravnine prvo izravnaj podlogu: ljepilo je skuplje od samorazlijevajuće mase.",
    g_gladz_t: "Koliko gleta za zid",
    g_gladz_d: "Glet se računa u kilogramima po kvadratu i milimetru sloja. Dva tanka sloja umjesto jednog debelog.",
    g_gladz_s1: "Izračunaj površinu zidova i stropa pa oduzmi prozore i vrata. Ta površina je polazište za svaki sloj.",
    g_gladz_s2: "Uzmi potrošnju s vreće: gipsani glet oko 1 kg/m² po milimetru, polimerni oko 1,2 kg/m². Pomnoži debljinom sloja.",
    g_gladz_s3: "Pomnoži brojem slojeva i podijeli težinom vreće. Zaokruži naviše — pola vreće se ne kupuje.",
    g_gladz_tip: "Na sirovoj žbuci prvi sloj ide deblje nego što etiketa pretpostavlja, jer popunjava neravnine. Računaj prvi sloj kao 1,5 mm, a drugi kao 0,5 mm, i prvo prajmeraj — bez prajmera glet vuče vodu i praši.",
    g_ocieplenie_t: "Izolacija kuće stiroporom",
    g_ocieplenie_d: "ETICS čine stiropor, ljepilo, tiplovi, mrežica, armirni sloj i žbuka. Sve se računa iz iste površine.",
    g_ocieplenie_s1: "Izračunaj površinu fasade: opseg zgrade puta visina, minus prozori i vrata. Špalete računaj zasebno ako ih izoliraš.",
    g_ocieplenie_s2: "Odaberi debljinu stiropora i prebroji pakete. Uz to tiplovi (tipično 6 po m², na uglovima i iznad 8 m više) i ljepilo — zasebno za lijepljenje, zasebno za armirni sloj.",
    g_ocieplenie_s3: "Kod mrežice dodaj oko 10 % na preklope, a tankoslojnu žbuku računaj iz njezine potrošnje po m².",
    g_ocieplenie_tip: "Broj tiplova nije jedan broj za cijelu kuću. Kutna zona ih traži gušće nego sredina zida, a iznad 8 m zgrada ulazi u višu vjetrovnu zonu. Prije narudžbe provjeri projekt ili upute sustava.",
    g_rozkroj_t: "Rezanje namještajne ploče s manje otpada",
    g_rozkroj_d: "Koliko ploča kupiti za popis elemenata i kako ih posložiti da otpad bude što manji. Širina reza također troši materijal.",
    g_rozkroj_s1: "Ispiši elemente: širina, duljina i komadi. Dodaj nadmjeru za kant ako se traka lijepi nakon rezanja.",
    g_rozkroj_s2: "Zadaj format ploče i širinu reza. Formatna pila uzme oko 3–4 mm po rezu; kod nekoliko desetaka rezova to su cijeli centimetri.",
    g_rozkroj_s3: "Odluči smiju li se elementi okretati. Ploča s teksturom ili dekorom ne smije i otpad raste — izračunaj obje varijante i usporedi.",
    g_rozkroj_tip: "Rezultat je plan rezanja, ne narudžba. Prije narudžbe provjeri leži li svaki element onako kako ga je algoritam okrenuo. Kod teksture okretanje mijenja izgled fronte i kad je mjera dobra.",
