    g_gladz_t: "Koliko gleta za zid",
    g_gladz_d: "Glet se računa u kilogramima po kvadratu i milimetru sloja. Dva tanka sloja umesto jednog debelog.",
    g_gladz_s1: "Izračunaj površinu zidova i plafona pa oduzmi prozore i vrata. Ta površina je polazište za svaki sloj.",
    g_gladz_s2: "Uzmi potrošnju sa džaka: gipsani glet oko 1 kg/m² po milimetru, polimerni oko 1,2 kg/m². Pomnoži debljinom sloja.",
    g_gladz_s3: "Pomnoži brojem slojeva i podeli težinom džaka. Zaokruži naviše — pola džaka se ne kupuje.",
    g_gladz_tip: "Na sirovom malteru prvi sloj ide deblje nego što etiketa pretpostavlja, jer popunjava neravnine. Računaj prvi sloj kao 1,5 mm, a drugi kao 0,5 mm, i prvo prajmeraj — bez prajmera glet vuče vodu i praši.",
    g_ocieplenie_t: "Izolacija kuće stiroporom",
    g_ocieplenie_d: "ETICS čine stiropor, lepak, tiplovi, mrežica, armirajući sloj i malter. Sve se računa iz iste površine.",
    g_ocieplenie_s1: "Izračunaj površinu fasade: obim zgrade puta visina, minus prozori i vrata. Špaletne računaj posebno ako ih izoluješ.",
    g_ocieplenie_s2: "Izaberi debljinu stiropora i prebroj pakete. Uz to tiplovi (tipično 6 po m², na uglovima i iznad 8 m više) i lepak — posebno za lepljenje, posebno za armirajući sloj.",
    g_ocieplenie_s3: "Kod mrežice dodaj oko 10 % na preklope, a tankoslojni malter računaj iz njegove potrošnje po m².",
    g_ocieplenie_tip: "Broj tiplova nije jedan broj za celu kuću. Ugaona zona ih traži gušće nego sredina zida, a iznad 8 m zgrada ulazi u višu vetrovnu zonu. Pre porudžbine proveri projekat ili uputstvo sistema.",
    g_rozkroj_t: "Sečenje nameštajne ploče sa manje otpada",
    g_rozkroj_d: "Koliko ploča kupiti za spisak elemenata i kako ih rasporediti da otpad bude što manji. Širina reza takođe troši materijal.",
    g_rozkroj_s1: "Ispiši elemente: širina, dužina i komadi. Dodaj nadmeru za kant ako se traka lepi posle sečenja.",
    g_rozkroj_s2: "Zadaj format ploče i širinu reza. Formatna testera uzme oko 3–4 mm po rezu; kod nekoliko desetina rezova to su celi centimetri.",
    g_rozkroj_s3: "Odluči smeju li se elementi okretati. Ploča sa teksturom ili dekorom ne sme i otpad raste — izračunaj obe varijante i uporedi.",
    g_rozkroj_tip: "Rezultat je plan sečenja, ne porudžbina. Pre porudžbine proveri da li svaki element leži onako kako ga je algoritam okrenuo. Kod teksture okretanje menja izgled fronta i kad je mera dobra.",
