    ck_life_google: "Secondo le regole di Google",
    ck_p_consent: "La tua decisione sull'analitica. Senza di essa il banner chiederebbe a ogni visita.",
    ck_p_lang: "La lingua scelta nel selettore, così la visita successiva parte subito in quella.",
    ck_p_currency: "La valuta in cui contiamo i tuoi prezzi. Scelta separatamente dalla lingua.",
    ck_p_theme: "Chiaro o scuro, se lo imposti a mano invece di lasciarlo al sistema.",
    ck_p_signed_in: "Il livello dell'account (LiczMat o LiczMat Pro) ricordato all'accesso. I calcolatori non caricano Firebase e devono comunque sapere se offrirti un account. Non contiene un indirizzo e-mail né altro su di te.",
    ck_p_remember: "Se resti connesso dopo la chiusura del browser. Lo imposti all'accesso o nel profilo; il valore vale solo per questo dispositivo.",
    ck_p_redirect: "Una protezione contro un ciclo di reindirizzamenti quando cambia la lingua.",
    ck_p_workspace: "I tuoi progetti, le stanze e le voci del preventivo salvati senza accedere.",
    ck_p_active: "In quale progetto salvare il risultato — sceglilo in “Aggiungi al progetto”.",
    ck_p_recent: "Quali calcolatori sono stati usati per ultimi, perché il pannello possa elencarli. Solo il nome dello strumento e una data, senza dati inseriti e senza risultati.",
    ck_p_ga: "Google Analytics: traffico del sito anonimo e aggregato. Scritto solo dopo che accetti.",
    ck_p_firebase: "La sessione di accesso in «Il mio account» e una copia locale dei dati dell'account. Solo dopo l'accesso.",
    ck_p_maps: "La mappa Google incorporata nella pagina dei negozi imposta file propri di Google quando si carica.",
    guide_calcs_back: "Guide che usano questo calcolatore",
    g_klej_t: "Quanta colla per piastrelle",
    g_klej_d: "Il consumo di colla segue la spatola dentata, e la spatola segue il formato della piastrella. Poi lo stucco, e le piastrelle stesse con una scorta per i tagli.",
    g_klej_s1: "Scegli la spatola per il formato. Piastrelle piccole: 6 mm. Gres 60×60: 8–10 mm. Grandi formati: 12 mm e doppia spalmatura.",
    g_klej_s2: "Moltiplica la superficie per il consumo del sacco e dividi per il peso del sacco. I valori tipici sono 4 kg/m² con spatola da 6 mm e 5 kg/m² con quella da 10 mm.",
    g_klej_s3: "Calcola lo stucco a parte: dipende dalla misura della piastrella, dal suo spessore e dalla larghezza della fuga. Conta le piastrelle con una scorta per i tagli.",
    g_klej_tip: "Il consumo sul sacco presuppone un fondo piano. Una parete storta beve molta più colla di quanto dica l'etichetta. Oltre i 5 mm circa di scarto, livella prima il fondo: la colla costa più del rasante.",
    g_gladz_t: "Quanto stucco per una parete",
    g_gladz_d: "Lo stucco si conta in chilogrammi per metro quadro per millimetro di strato. Due strati sottili invece di uno spesso.",
    g_gladz_s1: "Calcola la superficie di pareti e soffitto e togli finestre e porte. Quella superficie è il punto di partenza per ogni strato.",
    g_gladz_s2: "Prendi il consumo del sacco: stucco in gesso circa 1 kg/m² per millimetro, polimerico circa 1,2 kg/m². Moltiplica per lo spessore dello strato.",
    g_gladz_s3: "Moltiplica per il numero di strati e dividi per il peso del sacco. Arrotonda per eccesso: mezzo sacco non si compra.",
    g_gladz_tip: "Su un intonaco grezzo il primo strato va più spesso di quanto presuppone l'etichetta, perché riempie le irregolarità. Contalo come 1,5 mm e il secondo come 0,5 mm. Applica prima il primer: senza, lo stucco tira via acqua e sfarina.",
    g_ocieplenie_t: "Cappotto termico con polistirene",
    g_ocieplenie_d: "Un sistema ETICS è fatto di polistirene, colla, tasselli, rete, rasatura e rivestimento. Tutto si calcola dalla stessa superficie.",
    g_ocieplenie_s1: "Calcola la superficie della facciata: perimetro dell'edificio per l'altezza, meno finestre e porte. Conta a parte le spallette se le isoli.",
    g_ocieplenie_s2: "Scegli lo spessore del polistirene e conta i pacchi. Poi i tasselli: di solito 6 per m², di più agli angoli e sopra gli 8 m. Conta la colla due volte, una per l'incollaggio e una per la rasatura.",
    g_ocieplenie_s3: "Calcola circa il 10 % in più sulla rete per le sovrapposizioni e prendi il rivestimento sottile dal suo consumo per m².",
    g_ocieplenie_tip: "Il numero di tasselli non vale per tutta la casa. Agli angoli vanno più fitti, e sopra gli 8 m la zona di vento cambia. Controlla il progetto prima di ordinare.",
    g_rozkroj_t: "Taglio del pannello con meno scarto",
    g_rozkroj_d: "Quanti pannelli comprare per un elenco di pezzi e come disporli perché lo scarto sia il più piccolo possibile. Anche la lama porta via materiale.",
    g_rozkroj_s1: "Elenca i pezzi: larghezza, lunghezza e quantità. Aggiungi un margine per il bordo se il bordo si applica dopo il taglio.",
    g_rozkroj_s2: "Indica il formato del pannello e lo spessore di taglio. Una sezionatrice porta via circa 3–4 mm a ogni taglio; su qualche decina di tagli sono centimetri interi.",
    g_rozkroj_s3: "Decidi se i pezzi possono ruotare. Un pannello con venatura o disegno non può, e lo scarto cresce: calcola entrambi i casi e confronta.",
    g_rozkroj_tip: "Il risultato è un piano di taglio, non un ordine. Prima di ordinare controlla che ogni pezzo entri nel verso in cui l'algoritmo lo ha girato. Con una venatura, ruotare un pezzo cambia l'aspetto del fronte anche quando la misura è giusta.",
    nav_app_page: "L'app",
    apppage_title: "LiczMat per Android",
    apppage_lead: "I calcolatori LiczMat sul telefono. Funzionano senza internet; salvi ogni risultato in un progetto e lo assegni a una stanza.",
    apppage_web_link: "Calcolatori nel browser",
    apppage_h_result: "Risultato del calcolo",
    apppage_result_d: "Inserisci misure e materiale; l'app indica quante confezioni comprare e lo scarto. Il taglio calcola barre e pannelli includendo il taglio della lama.",
    apppage_h_project: "Progetti e stanze",
    apppage_project_d: "Salvi ogni calcolo in un progetto e lo assegni a una stanza. Dopo l'accesso si sincronizza tutto: progetti, stanze, calcoli, liste della spesa, materiali personalizzati, e nel Pro anche clienti e preventivi.",
    apppage_pro_line: "Prezzi, costi e preventivi PDF sono disponibili in LiczMat Pro",
    shot_project: "Progetto con calcoli assegnati alle stanze",
