    g_malowanie_t: "Hoeveel verf voor een kamer",
    g_malowanie_d: "Het oppervlak van wanden en plafond, openingen eraf, omgerekend naar hele blikken met een marge voor de tweede laag.",
    g_malowanie_s1: "Meet de kamer: lengte, breedte en hoogte. Omtrek maal hoogte geeft het wandoppervlak, lengte maal breedte het plafond.",
