    g_malowanie_tip: "Het rendement op het etiket gaat uit van een glad, voorgestreken oppervlak. Zuigende pleister drinkt meer verf, dus reken extra of strijk eerst voor.",
    g_plytki_t: "Tegels en lijm voor de badkamer",
    g_plytki_d: "Vloer en wanden in vierkante meters, een marge voor snijverlies, lijm en voegmiddel omgerekend naar zakken.",
    g_plytki_s1: "Meet de vloer en de wanden apart. Neem voor de wanden de omtrek maal de betegelde hoogte en trek er de deur en het raam af.",
    g_plytki_s2: "Tel een marge voor snijverlies op: 5–7% bij recht leggen, 10–15% bij groot formaat of diagonaal.",
    g_plytki_s3: "Reken de lijm uit het verbruik voor jouw lijmkam en het voegmiddel uit de tegelmaat en de voegbreedte.",
    g_plytki_tip: "Koop tegels uit één productiepartij. Partijen verschillen in tint en maatvoering, en een maand later is die partij uit de winkel.",
    g_panele_t: "Hoeveel vloerpanelen",
    g_panele_d: "Vloeroppervlak, een marge voor snijverlies en de omrekening naar hele pakken.",
    g_panele_s1: "Meet de vloer: lengte maal breedte. Meet nissen en erkers apart en tel ze erbij op.",
    g_panele_s2: "Tel een marge voor snijverlies op: 5% bij recht leggen langs de langste wand, 10% bij diagonaal leggen.",
    g_panele_s3: "Deel door het pakrendement op de verpakking en rond af naar hele pakken.",
    g_panele_tip: "Houd één heel pak over. Een beschadigde plank ruil je alleen als je precies hetzelfde decor hebt.",
