    note_wallpaper: "Bij een rapport wordt elke baan verlengd tot een heel veelvoud van het rapport, dus levert een rol minder banen op. Een rapport van 0 betekent behang zonder patroon dat moet aansluiten.",
    note_linear: "De zaagsnede wordt afgetrokken bij elke opeenvolgende zaagsnede in een profiel. Het zaagplan is mogelijk niet optimaal.",
    note_sheet: "Guillotinezagen: elke snede loopt over de hele plaat, zoals een plaatzaag werkt. Zet draaien uit als de plaat een nerf of een gericht patroon heeft.",
