    note_grout: "Het voegverbruik stijgt met de voegbreedte en de tegeldikte en daalt met de tegelmaat. Grote keramiek met een smalle voeg vraagt heel weinig.",
    note_masonry: "Het aantal stuks per m² volgt uit de blokmaat inclusief de voeg. Een marge van 5% dekt snijverlies en breuk tijdens transport.",
    note_insulation: "Het aantal pluggen hangt af van de bouwhoogte en de windzone — 6 per m² is gebruikelijk voor de begane grond en de eerste verdieping. Reken het gaas met 10% overlap.",
    note_studwall: "60 cm hart-op-hart is standaard onder een plaat van 1,2 m. Ga naar 40 cm onder een zwaardere afwerking of onder tegels. Platen worden voor beide zijden geteld.",
    note_ceiling: "40 cm tussen de CD-profielen en 90 cm tussen de hangers is een gebruikelijk plafond met één plaat. Zwaardere belasting vraagt kleinere afstanden.",
    note_drylining: "De methode met lijmkoeken werkt alleen op een vlakke, stevige ondergrond. Grotere afwijkingen vragen een metalen frame.",
    note_sheathing: "Het resultaat is een aantal hele platen zonder zaagplan. Wil je weten hoe je ze zaagt, gebruik dan de rekenmachine voor 2D-zagen.",
