    apppage_h_project: "Projecten en ruimtes",
    apppage_project_d: "Je slaat elke berekening op in een project en wijst het toe aan een kamer. Na inloggen synchroniseert alles: projecten, kamers, berekeningen, boodschappenlijstjes, eigen materialen, en in Pro ook klanten en offertes.",
