    g_malowanie_t: "Cuánta pintura para una habitación",
    g_malowanie_d: "Superficie de paredes y techo, huecos descontados, convertida en botes enteros con margen para la segunda mano.",
    g_malowanie_s1: "Mide la habitación: largo, ancho y alto. Perímetro por altura da la superficie de las paredes; largo por ancho, la del techo.",
    g_malowanie_s2: "Descuenta ventanas y puertas. Una ventana típica mide unos 1,5 m² y una puerta típica unos 1,8 m².",
    g_malowanie_s3: "Divide por el rendimiento del bote y multiplica por el número de manos. Redondea hacia arriba a botes enteros.",
    g_malowanie_tip: "El rendimiento de la etiqueta supone una superficie lisa e imprimada. Un revoco absorbente bebe más pintura, así que deja margen o imprima antes.",
    g_plytki_t: "Azulejos y adhesivo para el baño",
    g_plytki_d: "Suelo y paredes en metros cuadrados, un margen para los cortes, adhesivo y lechada convertidos en sacos.",
    g_plytki_s1: "Mide el suelo y las paredes por separado. Para las paredes toma el perímetro por la altura alicatada y descuenta la puerta y la ventana.",
    g_plytki_s2: "Añade un margen para los cortes: 5–7% en colocación recta, 10–15% en gran formato o en diagonal.",
    g_plytki_s3: "Calcula el adhesivo con el rendimiento de tu llana dentada y la lechada con el tamaño del azulejo y el ancho de la junta.",
    g_plytki_tip: "Compra los azulejos de un solo lote de fabricación. Los lotes cambian de tono y de calibre, y un mes después ese lote ya no estará en la tienda.",
    g_panele_t: "Cuántas lamas para el suelo",
    g_panele_d: "Superficie del suelo, un margen para los cortes y la conversión en paquetes enteros.",
    g_panele_s1: "Mide el suelo: largo por ancho. Mide los huecos y los salientes aparte y súmalos.",
    g_panele_s2: "Añade un margen para los cortes: 5% colocando recto a lo largo de la pared más larga, 10% colocando en diagonal.",
    g_panele_s3: "Divide por el rendimiento del paquete que viene en el embalaje y redondea hacia arriba a paquetes enteros.",
    g_panele_tip: "Guarda un paquete entero de repuesto. Una lama dañada solo se cambia si tienes exactamente el mismo decorado.",
    g_sciana_t: "Tabique de pladur: perfiles y placas",
    g_sciana_d: "Cuántos perfiles CW y UW, cuántas placas de yeso y cuánta lana mineral para un tabique de un tamaño dado.",
    g_sciana_s1: "Escribe el ancho y el alto del tabique y la separación entre montantes: normalmente 60 cm, o 40 cm bajo un acabado más pesado.",
    g_sciana_s2: "Los montantes CW salen de la separación; los canales UW son el suelo y el techo, es decir el doble del largo del tabique.",
    g_sciana_s3: "Cuenta las placas de las dos caras con un 10% de margen para los cortes. La lana se cuenta sobre la superficie del tabique.",
    g_sciana_tip: "Alterna las placas para que las juntas de una cara no coincidan con las de la otra. El tabique queda más rígido y las juntas se agrietan menos.",
    storespage_title: "Tiendas de construcción cerca de ti",
    storespage_lead: "Encuentra una tienda, almacén mayorista o de construcción por ubicación o nombre.",
    storespage_meta: "Encuentra una tienda de construcción cerca de ti: bricolajes, mayoristas y almacenes en un mapa, con la ruta hasta el que elijas.",
    note_coverage: "El rendimiento de la etiqueta (m²/l o m²/envase) supone una superficie lisa e imprimada. Un revoco absorbente gasta más. Descuenta los huecos solo si de verdad no los pintas.",
    note_waste: "Un margen del 5–7% basta en colocación recta. El gran formato, la diagonal o el aparejo a matajunta piden 10–15%. Compra de un solo lote.",
    note_wallpaper: "Con rapport cada tira se alarga hasta un múltiplo entero del rapport, así que un rollo da menos tiras. Un rapport de 0 significa papel sin dibujo que casar.",
    note_linear: "El grosor de corte se resta en cada corte consecutivo en una barra. El esquema de corte podría no ser óptimo.",
    note_sheet: "Corte a guillotina: cada corte atraviesa el tablero entero, como trabaja una seccionadora. Desactiva el giro cuando el tablero tenga veta o un dibujo direccional.",
    note_concrete: "La conversión supone un saco de 25 kg de mezcla seca con un rendimiento de unos 12,5 l de hormigón. Comprueba el rendimiento del saco: cambia según el fabricante.",
    note_mortar: "El consumo de adhesivo depende del dentado de la llana y de lo plano que esté el soporte. La cifra de aquí es la de ficha técnica; en una pared alabeada puede subir la mitad.",
    note_screed: "La conversión supone una densidad de unos 2,0 kg por litro de mortero. Las soleras de anhidrita y las aligeradas tienen otra densidad: comprueba el saco.",
    note_grout: "El consumo de lechada sube con el ancho de la junta y el grosor del azulejo, y baja con el tamaño. Un porcelánico grande con junta fina gasta muy poco.",
    note_masonry: "Las piezas por m² salen del tamaño del bloque con la junta incluida. Un margen del 5% cubre los cortes y las roturas en el transporte.",
    note_insulation: "El número de tacos depende de la altura y de la zona de viento: 6 por m² es lo típico en planta baja. Cuenta la malla con un 10% de solape.",
    note_studwall: "La separación de 60 cm es la estándar bajo una placa de 1,2 m. Baja a 40 cm bajo un acabado más pesado o bajo azulejo. Las placas se cuentan para las dos caras.",
    note_ceiling: "Perfiles CD cada 40 cm y colgadores cada 90 cm son un techo típico con una sola placa. Cargas mayores piden separaciones menores.",
    note_drylining: "El método por pelladas solo funciona sobre un soporte plano y firme. Desviaciones mayores piden una estructura metálica.",
    note_sheathing: "El resultado es un recuento de planchas enteras sin plan de corte. Si necesitas saber cómo cortarlas, usa la calculadora de corte de tableros 2D.",
