    ck_p_recent: "Qué calculadoras se usaron por última vez, para que el panel pueda listarlas. Solo el nombre de la herramienta y una fecha: sin datos escritos y sin resultados.",
    ck_p_ga: "Google Analytics: tráfico del sitio anónimo y agregado. Se escribe solo después de que aceptes.",
    ck_p_firebase: "La sesión de acceso en «Mi cuenta» y una copia local de los datos de la cuenta. Solo tras iniciar sesión.",
    ck_p_maps: "El mapa de Google incrustado en la página de tiendas deja archivos propios de Google al cargarse.",
    guide_calcs_back: "Guías que usan esta calculadora",
    g_klej_t: "Cuánto adhesivo para azulejos",
    g_klej_d: "El consumo de adhesivo sigue a la llana dentada, y la llana sigue al formato del azulejo. Después la lechada, y los azulejos con un margen para los cortes.",
    g_klej_s1: "Elige la llana según el formato. Azulejo pequeño: 6 mm. Porcelánico 60×60: 8–10 mm. Gran formato: 12 mm y doble encolado.",
    g_klej_s2: "Multiplica la superficie por el consumo del saco y divide por el peso del saco. Lo habitual es 4 kg/m² con llana de 6 mm y 5 kg/m² con la de 10 mm.",
    g_klej_s3: "Calcula la lechada aparte: depende del tamaño del azulejo, su grosor y el ancho de la junta. Cuenta los azulejos con un margen para los cortes.",
    g_klej_tip: "El consumo del saco supone un soporte plano. Una pared alabeada bebe mucho más adhesivo del que dice la etiqueta. Por encima de unos 5 mm de desviación, nivela antes: el adhesivo cuesta más que el mortero de nivelación.",
    g_gladz_t: "Cuánta masilla para una pared",
    g_gladz_d: "La masilla se cuenta en kilogramos por metro cuadrado y por milímetro de capa. Dos capas finas en lugar de una gruesa.",
    g_gladz_s1: "Calcula la superficie de paredes y techo y quita las ventanas y las puertas. Esa superficie es el punto de partida de cada capa.",
    g_gladz_s2: "Toma el consumo del saco: masilla de yeso unos 1 kg/m² por milímetro, polimérica unos 1,2 kg/m². Multiplica por el grosor de la capa.",
    g_gladz_s3: "Multiplica por el número de capas y divide por el peso del saco. Redondea hacia arriba: medio saco no se compra.",
    g_gladz_tip: "Sobre revoco en bruto la primera capa va más gruesa de lo que supone la etiqueta, porque rellena las irregularidades. Cuéntala como 1,5 mm y la segunda como 0,5 mm. Imprima antes: sin imprimación la masilla pierde agua y pulveriza.",
    g_ocieplenie_t: "Aislar la casa con poliestireno",
    g_ocieplenie_d: "Un sistema SATE lleva poliestireno, adhesivo, tacos, malla, capa de refuerzo y revestimiento. Todo sale de la misma superficie.",
    g_ocieplenie_s1: "Calcula la superficie de fachada: el perímetro del edificio por su altura, menos ventanas y puertas. Cuenta las mochetas aparte si también las aíslas.",
    g_ocieplenie_s2: "Elige el grosor del poliestireno y cuenta los paquetes. Después los tacos: normalmente 6 por m², más en las esquinas y por encima de 8 m. Cuenta el adhesivo dos veces, una para pegar y otra para la capa de refuerzo.",
    g_ocieplenie_s3: "Deja alrededor de un 10 % de más en la malla para los solapes y toma el revestimiento fino de su propio consumo por m².",
    g_ocieplenie_tip: "El número de tacos no vale para toda la casa. En las esquinas van más juntos, y por encima de 8 m cambia la zona de viento. Consulta el proyecto antes de pedir.",
    g_rozkroj_t: "Cortar un tablero con menos desperdicio",
    g_rozkroj_d: "Cuántos tableros comprar para una lista de piezas y cómo colocarlas para que el recorte sea lo menor posible. La sierra también se lleva material.",
    g_rozkroj_s1: "Lista las piezas: ancho, largo y cantidad. Añade un margen para el canto si el canto se pega después del corte.",
    g_rozkroj_s2: "Indica el formato del tablero y el grosor de corte. Una seccionadora se lleva unos 3–4 mm en cada corte; en unas decenas de cortes son centímetros enteros.",
    g_rozkroj_s3: "Decide si las piezas pueden girar. Un tablero con veta o dibujo no puede, y el desperdicio crece: calcula los dos casos y compara.",
    g_rozkroj_tip: "El resultado es un plan de corte, no un pedido. Antes de pedir, comprueba que cada pieza entra tal como la ha girado el algoritmo. Con veta, girar una pieza cambia el aspecto del frente aunque la medida sea correcta.",
    nav_app_page: "La app",
    apppage_title: "LiczMat para Android",
    apppage_lead: "Las calculadoras LiczMat en el teléfono. Funcionan sin internet; guardas cada resultado en un proyecto y lo asignas a una estancia.",
