    apppage_h_result: "Resultado del cálculo",
    apppage_result_d: "Indicas medidas y material; la app muestra cuántos paquetes comprar y el desperdicio. El corte calcula barras y tableros incluyendo el ancho de la sierra.",
    apppage_h_project: "Proyectos y estancias",
    apppage_project_d: "Guardas cada cálculo en un proyecto y lo asignas a una habitación. Tras iniciar sesión se sincroniza todo: proyectos, habitaciones, cálculos, listas de la compra, materiales propios, y en Pro también clientes y presupuestos.",
