    guide_all: "Tous les guides",
    g_malowanie_t: "Combien de peinture pour une pièce",
    g_malowanie_d: "Surface des murs et du plafond, ouvertures déduites, convertie en pots entiers avec une marge pour la deuxième couche.",
    g_malowanie_s1: "Mesure la pièce : longueur, largeur et hauteur. Périmètre fois hauteur donne la surface des murs, longueur fois largeur celle du plafond.",
    g_malowanie_s2: "Déduis les fenêtres et les portes. Une fenêtre courante fait environ 1,5 m², une porte courante environ 1,8 m².",
    g_malowanie_s3: "Divise par le rendement indiqué sur le pot et multiplie par le nombre de couches. Arrondis au pot entier supérieur.",
    g_malowanie_tip: "Le rendement de l'étiquette suppose une surface lisse et primaire appliqué. Un enduit absorbant boit plus de peinture : prévois une marge ou applique d'abord un primaire.",
    g_plytki_t: "Carrelage et colle pour la salle de bain",
    g_plytki_d: "Sol et murs en mètres carrés, une marge pour les coupes, colle et joint convertis en sacs.",
    g_plytki_s1: "Mesure le sol et les murs séparément. Pour les murs prends le périmètre fois la hauteur carrelée, puis déduis la porte et la fenêtre.",
    g_plytki_s2: "Ajoute une marge pour les coupes : 5–7 % en pose droite, 10–15 % en grand format ou en pose diagonale.",
    g_plytki_s3: "Calcule la colle à partir du rendement pour ton peigne et le joint à partir du format du carreau et de la largeur du joint.",
    g_plytki_tip: "Achète le carrelage d'un seul lot de fabrication. Les lots diffèrent de teinte et de calibre, et un mois plus tard ce lot ne sera plus en magasin.",
    g_panele_t: "Combien de lames pour le sol",
    g_panele_d: "Surface du sol, une marge pour les coupes et la conversion en paquets entiers.",
    g_panele_s1: "Mesure le sol : longueur fois largeur. Mesure les niches et les décrochés à part et ajoute-les.",
    g_panele_s2: "Ajoute une marge pour les coupes : 5 % en pose droite le long du mur le plus long, 10 % en pose diagonale.",
    g_panele_s3: "Divise par le rendement du paquet indiqué sur l'emballage et arrondis au paquet entier supérieur.",
    g_panele_tip: "Garde un paquet entier d'avance. Une lame abîmée ne se remplace que si tu as exactement le même décor.",
    g_sciana_t: "Cloison en placo : montants et plaques",
    g_sciana_d: "Combien de montants CW et UW, combien de plaques de plâtre et combien de laine minérale pour une cloison d'une taille donnée.",
    g_sciana_s1: "Saisis la largeur et la hauteur de la cloison, puis l'entraxe des montants : 60 cm en général, 40 cm sous une finition lourde.",
    g_sciana_s2: "Les montants CW découlent de l'entraxe ; les rails UW sont le sol et le plafond, donc deux fois la longueur de la cloison.",
    g_sciana_s3: "Compte les plaques pour les deux faces de la cloison avec 10 % de marge pour les coupes. La laine se compte sur la surface de la cloison.",
    g_sciana_tip: "Décale les plaques pour que les joints d'une face ne tombent pas sur ceux de l'autre. La cloison est plus rigide et les joints se fissurent moins.",
    storespage_title: "Magasins de matériaux près de chez toi",
    storespage_lead: "Trouve un magasin, grossiste ou dépôt de matériaux par emplacement ou par nom.",
    storespage_meta: "Trouve un magasin de matériaux près de chez toi : bricolage, négoces et dépôts sur une carte, avec l'itinéraire vers celui que tu choisis.",
    note_coverage: "Le rendement de l'étiquette (m²/l ou m²/emballage) suppose une surface lisse avec primaire. Un enduit absorbant consomme plus. Ne déduis les ouvertures que si tu ne les peins pas.",
    note_waste: "Une marge de 5–7 % suffit en pose droite. Le grand format, la pose diagonale ou à coupe de pierre demandent 10–15 %. Achète d'un seul lot.",
    note_wallpaper: "Avec un raccord, chaque lé est rallongé jusqu'à un multiple entier du raccord : un rouleau donne donc moins de lés. Un raccord de 0 désigne un papier sans motif à faire coïncider.",
    note_linear: "Le trait de scie est soustrait à chaque coupe consécutive dans une barre. Le plan de coupe peut ne pas être optimal.",
    note_sheet: "Découpe à la guillotine : chaque coupe traverse tout le panneau, comme travaille une scie à panneaux. Désactive la rotation quand le panneau a un fil ou un motif orienté.",
    note_concrete: "La conversion suppose un sac de 25 kg de mélange sec donnant environ 12,5 l de béton. Vérifie le rendement sur le sac : il change selon le fabricant.",
    note_mortar: "La consommation de colle dépend du peigne et de la planéité du support. Le chiffre indiqué est celui de la fiche technique ; sur un mur voilé il peut monter de moitié.",
    note_screed: "La conversion suppose une densité d'environ 2,0 kg par litre de mortier. Les chapes anhydrite et les chapes allégées ont une autre densité : vérifie le sac.",
    note_grout: "La consommation de joint augmente avec la largeur du joint et l'épaisseur du carreau, et baisse avec le format. Un grand grès à joint fin en demande très peu.",
    note_masonry: "Le nombre de pièces au m² découle de la taille du bloc, joint compris. Une marge de 5 % couvre les coupes et la casse au transport.",
    note_insulation: "Le nombre de chevilles dépend de la hauteur et de la zone de vent : 6 au m² est courant au rez-de-chaussée. Compte 10 % de recouvrement sur le treillis.",
    note_studwall: "Un entraxe de 60 cm est la norme sous une plaque de 1,2 m. Descends à 40 cm sous une finition plus lourde ou sous du carrelage. Les plaques se comptent pour les deux faces.",
    note_ceiling: "Fourrures CD tous les 40 cm et suspentes tous les 90 cm : c'est un plafond courant sous une seule plaque. Des charges plus lourdes demandent des entraxes plus serrés.",
    note_drylining: "La méthode des plots de colle ne marche que sur un support plan et sain. Des écarts plus importants demandent une ossature métallique.",
    note_sheathing: "Le résultat est un nombre de panneaux entiers, sans plan de coupe. Si tu veux savoir comment les couper, utilise le calculateur de découpe de panneaux 2D.",
    nav_dashboard: "Tableau de bord",
